{
  "titre": "Rituel tables de multiplication",
  "objectifGeneral": "Réactiver les tables de multiplication en 10 minutes",
  "notionsPivots": [
    "les tables de multiplication",
    "la multiplication",
    "les facteurs",
    "le produit",
    "la commutativité",
    "la mémorisation"
  ],
  "etapes": [
    {
      "titre": "Vérification rapide",
      "objectif": "identifier les résultats corrects",
      "cartes": [
        {
          "titre": "Vrai ou faux ?",
          "objectif": "valider ou invalider des propositions",
          "module": "TrueFalse",
          "palier": "entrainement",
          "duree": 2,
          "consigne": "Réponds par VRAI ou FAUX à chaque affirmation sur les tables de multiplication. Tu as 2 minutes pour valider ou invalider 5 propositions."
        }
      ]
    },
    {
      "titre": "Remplissage des résultats",
      "objectif": "compléter des calculs",
      "cartes": [
        {
          "titre": "Trouve les nombres manquants",
          "objectif": "remplir des cases vides",
          "module": "FillInTheBlanks",
          "palier": "entrainement",
          "duree": 4,
          "consigne": "Complète les cases vides avec le résultat exact des multiplications proposées. Tu as 4 minutes pour répondre à 8 calculs."
        }
      ]
    },
    {
      "titre": "Mots croisés des tables",
      "objectif": "retrouver des termes mathématiques",
      "cartes": [
        {
          "titre": "Mots croisés des tables",
          "objectif": "associer des définitions à des termes",
          "module": "Crossword",
          "palier": "entrainement",
          "duree": 4,
          "consigne": "Remplis la grille de mots croisés en trouvant les termes liés aux tables de multiplication. Tu as 4 minutes pour compléter 6 définitions."
        }
      ]
    }
  ]
}
